import { after } from 'next/server'

// Simulated analytics function
async function logPageView(path: string) {
  // Simulate network delay to prove non-blocking nature
  await new Promise(resolve => setTimeout(resolve, 1000))
  console.log(`[Analytics] Page view logged for: ${path} at ${new Date().toISOString()}`)
}

export default function Home() {
  console.log(`[Page] Rendering started at ${new Date().toISOString()}`)

  // Schedule the logging task using Next.js 'after'
  after(async () => {
    console.log(`[After] Scheduled task starting at ${new Date().toISOString()}`)
    await logPageView('/')
    console.log(`[After] Scheduled task finished at ${new Date().toISOString()}`)
  })

  console.log(`[Page] Rendering finished at ${new Date().toISOString()}`)

  return (
    <div style={{ fontFamily: 'system-ui, sans-serif', textAlign: 'center', padding: '50px' }}>
      <h1>Welcome!</h1>
      <p>This page logs a view to analytics without blocking the response.</p>
    </div>
  )
}

